// Keep full license texts for libraries bundled into renderer JavaScript, whose
// npm directories may be omitted from the packaged app. Never relicense them.
const fs = require("node:fs");
const path = require("node:path");

const BUNDLED = [
  ["motion", "LICENSE.md", "MIT"],
  ["framer-motion", "LICENSE.md", "MIT"],
  ["motion-dom", "LICENSE.md", "MIT"],
  ["motion-utils", "LICENSE.md", "MIT"],
  ["pdfjs-dist", "LICENSE", "Apache-2.0"],
];

function notices(root) {
  const lock = JSON.parse(fs.readFileSync(path.join(root, "package-lock.json"), "utf8"));
  const parts = [
    "# Third-party notices\n\n" +
    "Generated by scripts/bundle-notices.js from the locked installed packages.\n" +
    "These libraries are bundled into renderer JavaScript. Their original license\n" +
    "terms and copyrights remain in effect; the project's Apache license does not\n" +
    "replace them. Runtime npm packages retain their license files in node_modules.\n" +
    "Electron's LICENSE.electron.txt and LICENSES.chromium.html are included in\n" +
    "resources/licenses (Contents/Resources/licenses on macOS).\n\n" +
    "PDF character maps retain renderer/vendor/pdfjs/cmaps/LICENSE (Adobe BSD).\n" +
    "PDF fonts retain renderer/vendor/pdfjs/standard_fonts/LICENSE_FOXIT (BSD) and\n" +
    "LICENSE_LIBERATION (SIL Open Font License 1.1). Those files ship unchanged.\n",
  ];
  for (const [name, licenseFile, license] of BUNDLED) {
    const dir = path.join(root, "node_modules", name);
    const pkg = JSON.parse(fs.readFileSync(path.join(dir, "package.json"), "utf8"));
    if (pkg.version !== lock.packages["node_modules/" + name]?.version || pkg.license !== license) {
      throw new Error("Review changed bundled license/version: " + name);
    }
    const text = fs.readFileSync(path.join(dir, licenseFile), "utf8").trim();
    if (!text) throw new Error("Missing bundled license: " + name);
    parts.push(`## ${name} ${pkg.version} (${license})\n\n` +
      (name === "pdfjs-dist" ? "Copyright 2024 Mozilla Foundation\n\n" : "") +
      "```text\n" + text + "\n```\n");
  }
  return parts.join("\n");
}

if (require.main === module) {
  const root = path.join(__dirname, "..");
  fs.writeFileSync(path.join(root, "THIRD_PARTY_NOTICES.md"), notices(root));
}

module.exports = { notices };
